function screenHome(){if(!state.loggedIn)return `<section class="login-state"><div class="login-brand">AION Service</div><button class="login-btn" data-auth="login">Войти в демо</button></section>`;const q=state.pinned.slice(0,4);return `<div class="home-intro"><b>AION Service</b><span>Добрый день, Иван</span></div><div class="home-layout"><section class="card attention"><div class="attn-head"><b>Требует внимания</b></div><button class="attn-row" data-attention-order="125" data-attention-device="iPhone 13" data-attention-target="approval"><span class="attn-main"><b>№125 · iPhone 13</b><span>Нужно согласование</span><small>AION: клиент ждёт дольше обычного · <span class="why" data-why="approval">Почему?</span></small></span><span class="status overdue">Просрочено</span></button><button class="attn-row" data-attention-order="128" data-attention-device="iPhone 14" data-attention-target="repair"><span class="attn-main"><b>№128 · iPhone 14</b><span>Продолжить ремонт</span></span><span class="status part">Деталь получена</span></button><button class="attn-row" data-attention-order="124" data-attention-device="iPhone 13" data-attention-target="otk"><span class="attn-main"><b>№124 · iPhone 13</b><span>Передать на ОТК</span></span><span class="status otk">Независимый</span></button><button class="attn-row" data-attention-order="123" data-attention-device="iPhone 15" data-attention-target="payment"><span class="attn-main"><b>№123 · iPhone 15</b><span>Принять 2 500 ₽</span></span><span class="status time">До 15:00</span></button><button class="all-link" data-go="orders">Все 5 →</button></section><div class="home-side"><button class="home-primary" data-new="empty"><span class="action-icon">${ico('i-plus')}</span><span class="action-text"><b>Новый ремонт</b><small>Создать ремонт</small></span><span>›</span></button><div class="home-search" data-go="search"><span class="action-icon">${ico('i-search')}</span><span class="action-text"><b>Найти что угодно</b><small>Заказ · клиент · устройство</small></span><span class="search-tools"><button class="mini-tool" data-capture="qr" aria-label="QR">${ico('i-qr')}</button><button class="mini-tool" data-capture="photo" aria-label="Фото">${ico('i-camera')}</button><button class="mini-tool" data-capture="voice" aria-label="Голос">${ico('i-mic')}</button></span></div><section class="quick ${q.length?'show':''}"><div class="section-label">Быстрый доступ</div><div class="quick-grid">${q.map(id=>{const m=menu.find(x=>x[0]===id);return `<button class="quick-btn" data-go="${id}">${ico(m[1])}<span>${m[2]}</span></button>`}).join('')}</div></section></div></div>`}
function screenSearch(){return `<div class="section-label">Единый поиск</div><section class="card"><input class="input" id="searchInput" placeholder="Заказ, клиент, IMEI, телефон…" value="125"><div style="height:var(--sp)"></div><div class="search-source"><button class="source-btn" data-source="text">${ico('i-search')}<span>Текст</span></button><button class="source-btn" data-capture="qr">${ico('i-qr')}<span>QR</span></button><button class="source-btn" data-capture="photo">${ico('i-camera')}<span>Фото</span></button><button class="source-btn" data-capture="voice">${ico('i-mic')}<span>Голос</span></button></div><div style="height:var(--sp)"></div><button class="small-btn" data-search="run">Найти</button></section><section class="card" id="searchHint"><div class="match"><span class="action-icon">${ico('i-clipboard')}</span><span><b>Однозначное совпадение</b><small>Заказ №125 · iPhone 13 · Иван Иванов</small></span><button class="small-btn" data-go="order">Открыть</button></div></section>`}
function screenCapture(){const mode=currentParams.mode||'context';const labels={qr:'QR',photo:'Фото',voice:'Голос',context:'Контекст'};return `<div class="section-label">Дайте AION любой контекст</div><section class="card"><div class="context-title">${labels[mode]||'Контекст'}</div><div class="context-sub">Имя · телефон · устройство · IMEI · заказ · услуга · деталь · поставщик</div><div style="height:var(--sp)"></div><div class="search-source"><button class="source-btn ${mode==='qr'?'active':''}" data-capture="qr">${ico('i-qr')}<span>QR</span></button><button class="source-btn ${mode==='photo'?'active':''}" data-capture="photo">${ico('i-camera')}<span>Фото</span></button><button class="source-btn ${mode==='voice'?'active':''}" data-capture="voice">${ico('i-mic')}<span>Голос</span></button><button class="source-btn" data-go="search">${ico('i-search')}<span>Текст</span></button></div></section><section class="card"><div class="match"><span class="action-icon">${ico('i-phone')}</span><span><b>Возможное совпадение</b><small>iPhone 13 · Иван Иванов · заказ №125</small></span><button class="small-btn" data-confirm-match="order">Подтвердить</button></div></section><button class="small-btn ghost" data-new="capture">Начать новый ремонт с этим контекстом</button>`}
function contextWorkspace(title,sub,next,extra=''){return `<section class="card context-head"><div class="context-title">${title}</div><div class="context-sub">${sub}</div><div class="truth-grid"><div class="truth-line"><label>Сейчас</label><b>${extra||'iPhone 13 · ремонт №125'}</b></div><div class="truth-line"><label>Требует</label><b>${next}</b></div><div class="truth-line"><label>Следующее</label><b>${next}</b></div></div></section>`}
function screenClient(){return `${contextWorkspace('Иван Иванов','+7 900 123-45-67','Открыть текущий ремонт')}<section class="card"><div class="inline-actions"><button class="small-btn" data-go="device">Устройства</button><button class="small-btn" data-go="history">История</button><button class="small-btn" data-go="documents">Документы</button><button class="small-btn" data-new="client">Новый ремонт</button></div></section>`}
function screenDevice(){return `${contextWorkspace('iPhone 13','IMEI 356789012345678','Продолжить ремонт','Заказ №125 · диагностика завершена')}<section class="card"><div class="inline-actions"><button class="small-btn" data-go="order">Открыть заказ</button><button class="small-btn" data-new="device">Новый ремонт</button><button class="small-btn" data-go="documents">Документы</button></div></section>`}
function screenSimple(route,title,sub,ctxKey,ctxVal,icon){return `${contextWorkspace(title,sub,'Создать ремонт с известным контекстом',ctxVal)}<section class="card"><div class="match"><span class="action-icon">${ico(icon)}</span><span><b>${ctxVal}</b><small>Контекст будет перенесён в черновик</small></span><button class="small-btn" data-new="${ctxKey}">Новый ремонт</button></div></section>`}
function screenDraft(){const c=state.context;const rows=[['client','Клиент'],['device','Устройство'],['service','Услуга'],['part','Деталь'],['supplier','Поставщик']];return `<div class="section-label">Живой черновик</div><section class="card"><div class="context-title">Новый ремонт</div><div class="context-sub">Поля можно заполнять в любом порядке. Известное не вводится повторно.</div><div style="height:var(--sp)"></div><div class="form-list">${rows.map(([k,l])=>`<button class="form-row" data-fill="${k}"><span><label>${l}</label><b class="${c[k]?'known':'unknown'}">${c[k]||'Не указано'}</b></span><span class="check">${c[k]?'✓':'+'}</span></button>`).join('')}</div></section>`}
function screenDiagnostics(){return `<div class="section-label">Сейчас</div><section class="card"><div class="context-title">Диагностика</div><div class="context-sub">iPhone 13 · заказ №125</div><div style="height:var(--sp)"></div><div class="form-list"><div class="form-row"><span><label>Результат</label><b>Требуется замена дисплея</b></span><span class="check">✓</span></div><div class="form-row"><span><label>Стоимость</label><b>3 500 ₽</b></span><span class="check">✓</span></div></div></section>`}
function visibleOrderId(){return currentParams.orderId||'125'}
function visibleDevice(){return currentParams.device||'iPhone 13'}
function screenApproval(){const oid=visibleOrderId(),dev=visibleDevice();return `<div class="section-label">Согласование</div><section class="card"><div class="context-title">3 500 ₽</div><div class="context-sub">Иван Иванов · ${dev} · заказ №${oid}</div><div style="height:var(--sp)"></div><div class="truth-grid"><div class="truth-line"><label>Подтверждено</label><b>Диагностика · замена дисплея</b></div><div class="truth-line"><label>Требует</label><b>Решение клиента</b></div><div class="truth-line"><label>Следующее</label><b>Согласовать стоимость</b></div></div></section>`}
function screenRepair(){const oid=visibleOrderId(),dev=visibleDevice();return `<div class="section-label">Работа</div><section class="card"><div class="context-title">Замена дисплея</div><div class="context-sub">Заказ №${oid} · ${dev}</div><div style="height:var(--sp)"></div><div class="truth-grid"><div class="truth-line"><label>Сейчас</label><b>Ремонт выполняется</b></div><div class="truth-line"><label>Подтверждено</label><b>Согласовано 3 500 ₽</b></div><div class="truth-line"><label>Следующее</label><b>Завершить ремонт</b></div></div></section>`}
function screenOrder(){const o=state.order;let req='Согласование',next='Согласовать 3 500 ₽',block='Ремонт не может продолжиться без согласования',confirmed='Диагностика завершена · 09:10 · Петров';if(o.approved&&!o.repairDone){req='Ремонт';next='Начать ремонт';block='Нет'}if(o.repairDone&&!o.sentOtk){req='Независимый ОТК';next='Передать на ОТК';block='Выдача недоступна до ОТК'}if(o.sentOtk&&!o.otkPassed){req='Контроль качества';next='Провести ОТК';block='Выдача недоступна до ОТК'}if(o.otkPassed&&o.paid<o.total){req='Оплата';next='Принять 2 500 ₽';block='Выдача недоступна: осталось 2 500 ₽'}if(o.otkPassed&&o.paid>=o.total&&!o.issued){req='Выдача';next='Выдать клиенту';block='Нет'}if(o.issued){req='Завершение';next='Открыть документы';block='Нет'}return `<section class="card context-head"><div class="context-title">Заказ №125</div><div class="context-sub">iPhone 13 · Иван Иванов</div><div class="truth-grid"><div class="truth-line"><label>Подтверждено</label><b>${confirmed}${o.repairDone?' · ремонт завершён':''}${o.otkPassed?' · ОТК пройден':''}${o.paid>=o.total?' · оплата подтверждена':''}</b></div><div class="truth-line"><label>Требует</label><b>${req}</b></div><div class="truth-line blocker"><label>Блокирует</label><b>${block}</b></div><div class="truth-line"><label>Следующее</label><b>${next}</b></div></div><div class="proof"><span>Факты выводятся из подтверждённых событий</span><button data-proof="order">Почему?</button></div></section><section class="card"><div class="inline-actions"><button class="small-btn" data-go="documents">Документы</button><button class="small-btn ghost" data-go="client">Клиент</button><button class="small-btn ghost" data-go="device">Устройство</button></div></section>`}
function screenOtk(){const o=state.order,oid=visibleOrderId(),dev=visibleDevice();return `<div class="section-label">Контроль качества</div><section class="card otk-main"><div class="context-title">Заказ №${oid} · ${dev}</div><div class="person"><span class="avatar">П</span><span><b>Ремонт: Петров</b><small>Исполнитель не может подтвердить собственный ОТК</small></span></div><div class="person"><span class="avatar">А</span><span><b>Проверяет: Анна Смирнова</b><small>Независимый проверяющий</small></span></div>${o.otkPassed?`<div class="truth-line"><label>Результат</label><b>✓ ОТК пройден · ${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</b></div>`:`<div class="truth-line"><label>Сейчас</label><b>Обычный контроль без обязательного длинного checklist</b></div>`}<div class="detail-list ${o.otkProblem?'open':''}" id="otkDetails">${['Экран','Сенсор','Связь','Камеры','Динамики','Зарядка','Внешний вид','Комплектность'].map(x=>`<div class="detail-row"><span class="box on">✓</span><span>${x}</span></div>`).join('')}</div></section>`}
function screenPayment(){const o=state.order,oid=visibleOrderId(),dev=visibleDevice();const remain=o.total-o.paid;return `<div class="section-label">Оплата · заказ №${oid} · ${dev}</div><section class="card"><div class="money-grid"><div class="money-line"><span>Итого</span><b>12 500 ₽</b></div><div class="money-line"><span>Оплачено</span><b>${o.paid.toLocaleString('ru-RU')} ₽</b></div><div class="money-line"><span>Осталось</span><b>${Math.max(0,remain).toLocaleString('ru-RU')} ₽</b></div></div><div style="height:var(--sp)"></div>${o.payment==='checking'?`<div class="payment-state"><span class="spinner"></span><span>Проверяем результат оплаты… Повторять операцию не нужно.</span></div>`:o.paid>=o.total?`<div class="payment-state"><span class="check">✓</span><span>Оплата подтверждена · authoritative reread завершён</span></div>`:`<div class="payment-state"><span>${ico('i-money')}</span><span>Обычная оплата. Разрешение долга — отдельное исключение и не считается оплатой.</span></div>`}</section>`}